        });

        assert.equal(result, true);
        assert.deepEqual(merged, [{ workspace: 'IstiN', repository: 'trackstate', pullRequestId: '55', mergeMethod: 'squash' }]);
        assert.deepEqual(statusMoves, [
            { key: 'TS-51', statusName: 'Passed' },
