 *     prNumber?, prUrl?, failedNames?, error? }
 */
function attemptMerge(params) {
    const storyKey = params.ticket && params.ticket.key;
    if (!storyKey) {
        console.error('No storyKey provided');
        return { success: false, reason: 'missing_key' };
    }

